--radius-sm: 4px;
--radius-md: 6px;
--radius-lg: 10px;    /* 회의 카드, 컨트롤 */
--radius-xl: 16px;
--radius-full: 9999px;
--shadow-none: none;
--shadow-sm: 0 1px 3px rgba(0,0,0,0.30);
--shadow-md: 0 4px 12px rgba(0,0,0,0.40);
--shadow-lg: 0 8px 24px rgba(0,0,0,0.50);
--shadow-xl: 0 16px 40px rgba(0,0,0,0.60);
--duration-fast: 100ms;
--duration-base: 200ms;
--duration-slow: 350ms;
--ease-out: cubic-bezier(0.4, 0, 0.2, 1);
--ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
}
:root {
  /* Primary - Zoom Blue (다크 캔버스 위 가독성을 위해 밝은 쪽으로 시작) */
  --color-primary-50:  #0A1A3D;
  --color-primary-100: #0E2454;
  --color-primary-200: #133584;
  --color-primary-300: #1A4BB8;
  --color-primary-400: #2B6BF0;
  --color-primary-500: #3D82FF;  /* Zoom Blue 기본 — 다크 위 대비 확보 */
  --color-primary-600: #66A3FF;
  --color-primary-700: #99C2FF;
  --color-primary-800: #CCE0FF;
  --color-primary-900: #E5F0FF;

  /* Secondary - End/Leave Red */
  --color-secondary-500: #FF5A73;

  /* Neutral - 다크 반전 램프 */
  --color-neutral-0:    #0E1014;
  --color-neutral-50:   #16191F;
  --color-neutral-100:  #1F2329;
  --color-neutral-200:  #2D3138;
  --color-neutral-300:  #3D434A;
  --color-neutral-500:  #6B7178;
  --color-neutral-700:  #A4ABB7;
  --color-neutral-800:  #C5C9D0;
  --color-neutral-900:  #E6E8EC;
  --color-neutral-1000: #FFFFFF;

  /* Semantic - 다크 위 가독성 */
  --color-success-bg: #13321F;
  --color-success-fg: #4ED98A;
  --color-warning-bg: #3A2C0E;
  --color-warning-fg: #F0B43E;
  --color-error-bg:   #3A1418;
  --color-error-fg:   #FF6B82;
  --color-info-bg:    #0E2454;
  --color-info-fg:    #5C9CFF;

  /* Surface */
  --bg-base:     #1F2329;
  --bg-subtle:   #16191F;
  --bg-elevated: #2D3138;
  --bg-overlay:  rgba(7,8,11,0.66);

  /* Text */
  --text-primary:    #FFFFFF;
  --text-secondary:  #A4ABB7;
  --text-tertiary:   #6B7178;
  --text-on-primary: #FFFFFF;
  --text-disabled:   #5C6168;

  /* Border */
  --border-default: #3D434A;
  --border-subtle:  #2D3138;
  --border-strong:  #4D535C;
  --border-focus:   #3D82FF;

  /* Meeting view - 테마와 무관하게 영상 집중도를 유지하는 캔버스 */
  --meeting-stage: #111317;
  --meeting-tile: #24272D;
  --meeting-speaker: #23D959;
  --meeting-nameplate: rgba(0,0,0,0.72);
}

[data-theme="light"] {
  /* 원본 라이트 테마 — 토글 시 복원 */
  --color-primary-50:  #E5F0FF;
  --color-primary-100: #CCE0FF;
  --color-primary-200: #99C2FF;
  --color-primary-300: #66A3FF;
  --color-primary-400: #2B7AF7;
  --color-primary-500: #0B5CFF;
  --color-primary-600: #0048D9;
  --color-primary-700: #0036A8;
  --color-primary-800: #002577;
